import {
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  Color
} from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh } = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new ThreeGroup();
  const timelines = [];

  // 1. Stage / Backdrop Plane (~7x6 units at z=-2.5) to satisfy visual laws
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.85
  });
  const backdrop = new ThreeMesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // 2. Sprite Plane (using the specified source rect: 0, 0, 512, 320 -> Aspect Ratio 1.6)
  const width = 1.6;
  const height = 1.0;
  const spriteGeo = new PlaneGeometry(width, height);
  const spriteMat = new MeshBasicNodeMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: 1.0
  });

  const spriteMesh = new ThreeMesh(spriteGeo, spriteMat);
  group.add(spriteMesh);

  // Load the visual grain texture if available to satisfy subtle grain theme
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      spriteMat.color.set('#ffffff'); // Reset host color so map isn't tinted black
      spriteMat.map = texture;
      spriteMat.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load theme texture, falling back to clean solid.', err);
    });
  }

  // 3. Render Text Content (Plain string formatted via ctx.fontAtlas)
  // Text content source from specification: "Features 3" (headline, 39px -> scale to ~0.15 scene units)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textStr = items[0]?.text ?? "Features 3";

  // Position text slightly in front of the sprite card
  const textObj = ctx.fontAtlas.createText(textStr, {
    fontSize: 39,
    color: colors.paper,
    align: 'center'
  });
  textObj.position.set(0, 0, 0.05);
  textObj.scale.setScalar(0.0035); // Scale down pixel font coordinates to webgl units
  group.add(textObj);

  // Accent Sub-line to emphasize the "Features 3" label
  const accentLineGeo = new PlaneGeometry(0.3, 0.015);
  const accentLineMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent)
  });
  const accentLine = new ThreeMesh(accentLineGeo, accentLineMat);
  accentLine.position.set(0, -0.2, 0.04);
  group.add(accentLine);

  // 4. Subtle Rise-in Entrance Animation (using specified GSAP vocabulary)
  group.position.y -= 0.2;
  group.scale.set(0.9, 0.9, 0.9);

  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  tl.to(group.position, { y: '+=0.2', duration: 0.7 });
  tl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9 }, '<');

  timelines.push(tl);

  // Clean-up handler to meet requirements
  group.userData = {
    handlers: {},
    cleanup() {
      timelines.forEach((t) => t.kill());
      backdropGeo.dispose();
      backdropMat.dispose();
      spriteGeo.dispose();
      spriteMat.dispose();
      accentLineGeo.dispose();
      accentLineMat.dispose();
    }
  };

  return group;
}
